      tue:{enabled:true,modalityId:'mod_personal',capacity:4,windows:[{start:'06:00',end:'10:00'},{start:'16:00',end:'20:00'}]},
      wed:{enabled:true,modalityId:'mod_personal',capacity:4,windows:[{start:'06:00',end:'10:00'},{start:'16:00',end:'20:00'}]},
      thu:{enabled:true,modalityId:'mod_personal',capacity:4,windows:[{start:'06:00',end:'10:00'},{start:'16:00',end:'20:00'}]},
      fri:{enabled:true,modalityId:'mod_personal',capacity:4,windows:[{start:'06:00',end:'11:00'}]},
