    if(bodyCompositionMethodNeedsSex(ma)&&String(a?.referenceSex||'')!==String(b?.referenceSex||''))return 'referências de equação diferentes';
    if(longitudinal&&String(a?.bodyComposition?.formulaVersion||BODY_COMPOSITION_FORMULA_VERSION)!==String(b?.bodyComposition?.formulaVersion||BODY_COMPOSITION_FORMULA_VERSION))return 'versões de fórmula diferentes';
