    if(method==='jp3')return sex==='female'?['triceps','suprailiac','thigh']:sex==='male'?['chest','abdomen','thigh']:[];
    if(method==='jp7')return ['chest','midaxillary','triceps','subscapular','abdomen','suprailiac','thigh'];
