    if((method==='jp7'||method==='durnin4')&&!['male','female'].includes(sex))return {method,methodLabel:cfg.label,family:cfg.family,...massResult(null),bodyDensity:null,skinfoldSum:null,complete:false,note:'Selecione o sexo de referência para aplicar a equação.'};
