    const date=String(fd.get('date')||isoToday()),externalPercent=num('externalBodyFatPercent'),externalMeasurement={bodyFatPercent:externalPercent,method:bodyCompositionNormalizeText(fd.get('externalBodyFatMethod')),equipment:bodyCompositionNormalizeText(fd.get('externalBodyFatEquipment')),date:String(fd.get('externalBodyFatDate')||date),notes:bodyCompositionNormalizeText(fd.get('externalBodyFatNotes')),source:'external'};
