      const chipY=y+218;setFont(13,'700');ctx.fillStyle='#2b2d31';assessmentReportShareRoundRect(ctx,M+160,chipY,250,27,13);ctx.fill();text(`OBJETIVO  ${objective||'Não definido'}`,M+174,chipY+6,12,'700','#d8d8d4');assessmentReportShareRoundRect(ctx,M+426,chipY,230,27,13);ctx.fill();text(`ESTÁGIO  ${stage||'Não definido'}`,M+440,chipY+6,12,'700','#d8d8d4');
