    const bmi=assessmentBMI(a),ircq=assessmentIRCQ(a),comp=bodyCompositionReferenceResult(a,student),age=ageOnDate(student.birthDate,a.date),reportType=assessmentReportType(studentId,assessmentId),studio=String(state.settings?.studioName||brandStudioName());
