    if(Number(a.heightCm)>0)summary.push(assessmentReportMetric('Altura',`${assessmentNumber(a.heightCm,1)} cm`,'Registro da avaliação'));
    if(bmi!=null)summary.push(assessmentReportMetric('IMC',assessmentNumber(bmi,1),'Índice de massa corporal'));
