  function workspaceShortId(){
    const id=String(state.workspace?.id||'');
    return id?`…${id.slice(-8).toUpperCase()}`:'—';
  }


  function commercialOwner(){
    return state.commercial?.owner&&typeof state.commercial.owner==='object'?state.commercial.owner:{name:'',email:'',configuredAt:null,updatedAt:null};
  }

  function commercialInstallation(){
    if(!state.commercial||typeof state.commercial!=='object')state.commercial=normalizeCommercial();
    if(!state.commercial.installation?.id)state.commercial=normalizeCommercial(state.commercial);
    return state.commercial.installation;
  }

  function installationShortId(){
    const id=String(commercialInstallation()?.id||'');
    return id?`…${id.slice(-8).toUpperCase()}`:'—';
  }

  function supportAccessCode(){
    const clean=value=>String(value||'').replace(/[^a-z0-9]/gi,'').toUpperCase();
    const ws=clean(state.workspace?.id).slice(-4).padStart(4,'0');
    const inst=clean(commercialInstallation()?.id).slice(-4).padStart(4,'0');
    return `${ws}-${inst}`;
  }

  function commercialOwnerConfigured(){
    return Boolean(String(commercialOwner()?.name||'').trim());
  }

  function commercialPlanLabel(){
    const plan=String(state.commercial?.license?.plan||'local');
    return ({local:'Local',trial:'Teste',starter:'Starter',pro:'Pro',studio:'Studio'})[plan]||'Local';
  }

  function commercialLicense(){
    state.commercial=normalizeCommercial(state.commercial);
    return state.commercial.license;
  }

  function commercialLicenseStatusLabel(){
    const status=String(commercialLicense()?.status||'local-active');
    return ({'local-active':'Ativo local','not-configured':'Não vinculada',trial:'Período de teste',active:'Ativa','past-due':'Pagamento pendente',suspended:'Suspensa',expired:'Expirada'})[status]||'Ativo local';
  }

  function commercialLicenseTone(){
    const status=String(commercialLicense()?.status||'local-active');
    if(['active','trial','local-active'].includes(status))return 'good';
    if(status==='past-due')return 'warn';
    if(['suspended','expired'].includes(status))return 'danger';
    return 'neutral';
  }

  function licenseDateLabel(value,fallback='Não aplicável'){
    if(!value)return fallback;
    const d=new Date(value);return Number.isNaN(d.getTime())?fallback:new Intl.DateTimeFormat('pt-BR',{dateStyle:'medium'}).format(d);
  }

  function openPlanLicenseCenter(){
    state.commercial=normalizeCommercial(state.commercial);
    const license=commercialLicense(),local=license.plan==='local'&&license.source==='local',statusLabel=commercialLicenseStatusLabel(),tone=commercialLicenseTone();
    const renewal=local?'Não aplicável':licenseDateLabel(license.renewalAt||license.validUntil,'Não informado');
    const validation=license.checkedAt?formatDateTimeBR(license.checkedAt):(local?'Validação local':'Ainda não validada');
    openModal('Plano e licença',`<div class="license-center-hero ${tone}"><span>${['good'].includes(tone)?'✓':tone==='warn'?'!':tone==='danger'?'×':'MB'}</span><div><small>ACESSO ATUAL</small><strong>Plano ${escapeHTML(commercialPlanLabel())}</strong><p>${local?'Uso neste dispositivo • sem assinatura ou cobrança vinculada.':`Status da licença: ${escapeHTML(statusLabel)}.`}</p></div></div><div class="license-center-grid"><div><span>Status</span><strong>${escapeHTML(statusLabel)}</strong></div><div><span>Licença online</span><strong>${license.source==='online'?'Vinculada':'Não vinculada'}</strong></div><div><span>Renovação</span><strong>${escapeHTML(renewal)}</strong></div><div><span>Última validação</span><strong>${escapeHTML(validation)}</strong></div></div><div class="account-center-section"><div class="section-overline">IDENTIFICAÇÃO</div><div class="account-device-grid"><div><span>Instalação</span><strong>${escapeHTML(installationShortId())}</strong></div><div><span>Suporte</span><strong>${escapeHTML(supportAccessCode())}</strong></div></div><button class="btn btn-secondary btn-small account-copy-code" id="copyLicenseSupportCode" type="button">Copiar código de suporte</button></div><div class="notice compact"><strong>Preparado para a próxima etapa comercial.</strong><br>Quando uma licença online for vinculada no futuro, esta mesma tela poderá mostrar plano, validade e renovação. Nada é simulado nesta versão e seus dados locais continuam funcionando normalmente.</div><div class="modal-actions"><button type="button" class="btn btn-primary" data-close-modal>Concluir</button></div>`);
    $('#copyLicenseSupportCode')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(supportAccessCode());toast('Código de suporte copiado.')}catch{toast(`Código de suporte: ${supportAccessCode()}`)}});
  }

  function openProfessionalAccountCenter(){
    state.commercial=normalizeCommercial(state.commercial);
    const owner=commercialOwner(),installation=commercialInstallation(),configured=commercialOwnerConfigured();
    openModal('Conta e instalação',`<div class="account-center-hero ${configured?'ready':''}"><span>${configured?'✓':'MB'}</span><div><small>CONTA LOCAL</small><strong>${configured?escapeHTML(owner.name):'Configure o proprietário'}</strong><p>${configured?'Perfil comercial salvo somente neste dispositivo.':'Identifique quem administra este Studio sem criar login ou cobrança.'}</p></div></div><form id="commercialAccountForm" class="form-grid"><div class="account-center-section"><div class="section-overline">PROPRIETÁRIO</div><div class="field"><label>Nome do responsável</label><input name="ownerName" maxlength="80" autocomplete="name" value="${escapeHTML(owner.name||'')}" placeholder="Ex.: João Silva" /></div><div class="field"><label>E-mail <span class="muted">(opcional)</span></label><input name="ownerEmail" type="email" maxlength="120" autocomplete="email" value="${escapeHTML(owner.email||'')}" placeholder="contato@studio.com" /></div></div><div class="account-center-section"><div class="section-overline">ESTE DISPOSITIVO</div><div class="field"><label>Nome do dispositivo</label><input name="deviceLabel" maxlength="40" value="${escapeHTML(installation.label||'Este dispositivo')}" placeholder="Ex.: Celular principal" /></div><div class="account-device-grid"><div><span>Instalação</span><strong>${escapeHTML(installationShortId())}</strong></div><div><span>Código de suporte</span><strong>${escapeHTML(supportAccessCode())}</strong></div></div><button class="btn btn-secondary btn-small account-copy-code" id="copyAccountSupportCode" type="button">Copiar código de suporte</button></div><div class="account-center-section account-plan-box"><div><span>Plano atual</span><strong>${escapeHTML(commercialPlanLabel())}</strong><small>${escapeHTML(commercialLicenseStatusLabel())} • nenhuma cobrança vinculada nesta etapa.</small></div><button class="btn btn-secondary btn-small" id="openPlanLicenseFromAccount" type="button">Ver detalhes</button></div><div class="notice compact">Conta online, assinatura e sincronização não são simuladas. Esta etapa cria uma identificação profissional e estável para o proprietário e para este aparelho, preparando a futura ativação comercial.</div><div class="modal-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancelar</button><button class="btn btn-primary" type="submit">Salvar conta local</button></div></form>`);
    $('#copyAccountSupportCode')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(supportAccessCode());toast('Código de suporte copiado.')}catch{toast(`Código de suporte: ${supportAccessCode()}`)}});
    $('#openPlanLicenseFromAccount')?.addEventListener('click',()=>{closeModal();openPlanLicenseCenter()});
    $('#commercialAccountForm')?.addEventListener('submit',e=>{
      e.preventDefault();
      const data=new FormData(e.currentTarget),now=new Date().toISOString();
      const name=String(data.get('ownerName')||'').trim().slice(0,80),email=String(data.get('ownerEmail')||'').trim().slice(0,120),label=String(data.get('deviceLabel')||'').trim().slice(0,40)||'Este dispositivo';
      if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return toast('Confira o e-mail informado.');
      state.commercial=normalizeCommercial(state.commercial);
      state.commercial.owner={...state.commercial.owner,name,email,configuredAt:state.commercial.owner?.configuredAt||(name?now:null),updatedAt:now};
      state.commercial.installation={...state.commercial.installation,label};
      addAudit('Conta local atualizada',`${name?'Proprietário configurado':'Proprietário não informado'} • ${label} • ${installationShortId()}`);
      saveState();closeModal();renderSettings();toast('Conta local atualizada com segurança.');
    });
  }

  function approxStateBytes(source=state){
    try{return new Blob([JSON.stringify(source)]).size}catch{return 0}
  }

  function formatBytes(bytes=0){
    const n=Math.max(0,Number(bytes)||0);
    if(n<1024)return `${n} B`;
    if(n<1024*1024)return `${(n/1024).toFixed(n<10240?1:0)} KB`;
    return `${(n/1024/1024).toFixed(2)} MB`;
  }

  function duplicateIds(rows=[]){
    const seen=new Set(),dup=new Set();
    (Array.isArray(rows)?rows:[]).forEach(row=>{const id=String(row?.id||'').trim();if(!id)return;if(seen.has(id))dup.add(id);else seen.add(id)});
    return [...dup];
  }

  function backupAgeDays(){
    const raw=state.settings?.lastBackupAt;if(!raw)return null;
    const d=new Date(raw);if(Number.isNaN(d.getTime()))return null;
    return Math.max(0,Math.floor((Date.now()-d.getTime())/86400000));
  }

  function runCommercialIntegrityCheck(){
    const checks=[];
    const push=(id,label,status,detail)=>checks.push({id,label,status,detail});
    const workspaceOk=Boolean(state.workspace?.id&&state.workspace?.createdAt);
    push('workspace','Workspace do Studio',workspaceOk?'ok':'danger',workspaceOk?`Identidade ${workspaceShortId()} ativa.`:'Identidade lógica ausente. Faça backup antes de qualquer alteração.');
    push('schema','Esquema de dados',Number(state.version)===DATA_SCHEMA_VERSION?'ok':'danger',`Estado V${Number(state.version)||'—'} • esperado V${DATA_SCHEMA_VERSION}.`);
    const commercialOk=Number(state.commercial?.schemaVersion)===COMMERCIAL_SCHEMA_VERSION&&Boolean(state.commercial?.installation?.id);
    push('commercial','Conta e instalação',commercialOk?'ok':'danger',commercialOk?`Estrutura V${COMMERCIAL_SCHEMA_VERSION} • instalação ${installationShortId()} • proprietário ${commercialOwnerConfigured()?'configurado':'ainda não informado'}.`:'Estrutura comercial ou identidade desta instalação ausente.');
    const license=commercialLicense(),licenseOk=Boolean(license&&license.plan&&license.status&&license.source);
    push('license','Plano e licença',licenseOk?'ok':'danger',licenseOk?(license.plan==='local'&&license.source==='local'?`Plano Local ativo • licença online não vinculada • sem cobrança.`:`Plano ${commercialPlanLabel()} • ${commercialLicenseStatusLabel()} • origem ${license.source}.`):'Estrutura de licença ausente ou inválida.');
    const arrays=['students','payments','expenses','physicalAssessments','posturalAssessments','auditLog','trash'];
    const objects=['schedule','attendance','makeups','settings'];
    const invalid=[...arrays.filter(k=>!Array.isArray(state[k])),...objects.filter(k=>!state[k]||typeof state[k]!=='object'||Array.isArray(state[k]))];
    push('structure','Estrutura principal',invalid.length?'danger':'ok',invalid.length?`Campos inválidos: ${invalid.join(', ')}.`:'Coleções essenciais estão no formato esperado.');
    const duplicateGroups=[['alunos',duplicateIds(state.students)],['receitas',duplicateIds(state.payments)],['gastos',duplicateIds(state.expenses)],['avaliações físicas',duplicateIds(state.physicalAssessments)],['avaliações posturais',duplicateIds(state.posturalAssessments)]].filter(([,ids])=>ids.length);
    push('ids','Identificadores únicos',duplicateGroups.length?'danger':'ok',duplicateGroups.length?`Duplicidades detectadas em ${duplicateGroups.map(([name,ids])=>`${name} (${ids.length})`).join(', ')}.`:'Nenhuma duplicidade crítica de ID encontrada.');
    const op=state.settings?.operationConfig,mods=Array.isArray(op?.modalities)?op.modalities:[];
    const modDup=duplicateIds(mods);
    push('agenda','Configuração da Agenda',(!op||!mods.length||modDup.length)?'danger':'ok',!op?'Configuração operacional ausente.':!mods.length?'Nenhuma modalidade configurada.':modDup.length?`${modDup.length} modalidade(s) com ID duplicado.`:`${activeScheduleDays().length} dia(s) ativo(s) • ${mods.filter(x=>x.enabled).length} modalidade(s) habilitada(s).`);
    const bytes=approxStateBytes();
    const storageStatus=bytes>=4.5*1024*1024?'danger':bytes>=3.5*1024*1024?'warn':'ok';
    push('storage','Tamanho local',storageStatus,`${formatBytes(bytes)} utilizados pelo estado principal${storageStatus==='warn'?' • atenção ao crescimento de imagens e histórico.':storageStatus==='danger'?' • próximo do limite comum de armazenamento local.':''}`);
    const age=backupAgeDays();
    const backupStatus=age===null?'warn':age>30?'danger':age>7?'warn':'ok';
    push('backup','Backup recente',backupStatus,age===null?'Nenhum backup registrado neste aparelho.':age===0?'Backup realizado hoje.':`Último backup há ${age} dia(s) • V${state.settings?.lastBackupVersion||'—'}.`);
    const swSupported='serviceWorker' in navigator,swControlled=Boolean(navigator.serviceWorker?.controller);
    push('pwa','Camada de atualização',!swSupported?'warn':swControlled?'ok':'warn',!swSupported?'Service Worker não suportado neste navegador.':swControlled?'Service Worker ativo e controlando esta instalação.':'Service Worker disponível, mas ainda sem controle desta sessão.');
    const cryptoOk=Boolean(globalThis.crypto?.subtle&&globalThis.TextEncoder);
    push('crypto','Validação criptográfica de backup',cryptoOk?'ok':'warn',cryptoOk?'SHA-256 disponível para novos backups.':'SHA-256 indisponível neste ambiente; backups continuam compatíveis, mas sem verificação criptográfica local.');
    const danger=checks.filter(x=>x.status==='danger').length,warn=checks.filter(x=>x.status==='warn').length;
    const status=danger?'danger':warn?'warn':'ok';
    return {checks,status,danger,warn,bytes,summaryLabel:danger?'Ação necessária':warn?'Atenção':'Tudo certo'};
  }

  function supportReportText(result=runCommercialIntegrityCheck()){
    const counts=backupSummaryFor(state),standalone=window.matchMedia?.('(display-mode: standalone)')?.matches||navigator.standalone===true;
    const lines=[
      'MB Gestor Luxury Pro — Relatório de suporte',
      `Gerado em: ${new Date().toLocaleString('pt-BR')}`,
      `Versão do app: ${APP_VERSION}`,
      `Esquema de dados: ${DATA_SCHEMA_VERSION}`,
      `Workspace: ${workspaceShortId()}`,
      `Modo: ${state.workspace?.mode||'local'}`,
      `Base comercial: V${state.commercial?.schemaVersion||'—'} • conta ${state.commercial?.accountMode||'local'} • plano ${state.commercial?.license?.plan||'local'} • licença ${state.commercial?.license?.status||'—'}`,
      `Instalação: ${installationShortId()} • proprietário configurado ${commercialOwnerConfigured()?'sim':'não'} • código de suporte ${supportAccessCode()}`,
      `Execução: ${standalone?'PWA instalada':'navegador'} • online ${navigator.onLine===false?'não':'sim'}`,
      `Armazenamento do estado: ${formatBytes(result.bytes)}`,
      `Último backup: ${state.settings?.lastBackupAt?formatDateTimeBR(state.settings.lastBackupAt):'não registrado'} • versão ${state.settings?.lastBackupVersion||'—'}`,
      '',
      'CONTAGENS (sem nomes, telefones ou valores)',
      `Alunos: ${counts.students}`,
      `Receitas: ${counts.payments}`,
      `Gastos: ${counts.expenses}`,
      `Registros de aula: ${counts.attendanceRecords}`,
      `Avaliações físicas: ${(state.physicalAssessments||[]).length}`,
      `Avaliações posturais: ${(state.posturalAssessments||[]).length}`,
      '',
      `DIAGNÓSTICO: ${result.summaryLabel} • ${result.danger} crítico(s) • ${result.warn} atenção(ões)`,
      ...result.checks.map(c=>`[${c.status.toUpperCase()}] ${c.label}: ${c.detail}`),
      '',
      'Privacidade: este relatório não inclui nomes de alunos, dados do proprietário, contatos, valores financeiros, fotos, logotipos ou conteúdo clínico/avaliativo.'
    ];
    return lines.join('\n');
  }

  function downloadText(name,text){
    // V12.5.1 • BOM UTF-8 + CRLF: evita mojibake em visualizadores de texto do Android/Samsung.
    const utf8Text=`\uFEFF${String(text??'').replace(/\r?\n/g,'\r\n')}`;
    const blob=new Blob([utf8Text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');
    a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200);
  }

  function openCommercialDiagnostics(){
    const result=runCommercialIntegrityCheck();
    const iconFor=status=>status==='ok'?'✓':status==='warn'?'!':'×';
    openModal('Segurança e diagnóstico',`<div class="diagnostic-hero ${result.status}"><span>${iconFor(result.status)}</span><div><strong>${escapeHTML(result.summaryLabel)}</strong><small>${result.danger} crítico(s) • ${result.warn} atenção(ões) • ${escapeHTML(formatBytes(result.bytes))} locais</small></div></div><div class="diagnostic-list">${result.checks.map(c=>`<div class="diagnostic-row ${c.status}"><b>${iconFor(c.status)}</b><div><strong>${escapeHTML(c.label)}</strong><span>${escapeHTML(c.detail)}</span></div></div>`).join('')}</div><div class="notice compact">Verificação somente leitura: esta tela não altera alunos, agenda, financeiro, avaliações ou configurações.</div><div class="modal-actions diagnostic-actions"><button class="btn btn-secondary" data-close-modal>Fechar</button><button class="btn btn-secondary" id="copySupportReport">Copiar relatório</button><button class="btn btn-primary" id="downloadSupportReport">Baixar relatório</button></div>`);
    const report=supportReportText(result);
    $('#downloadSupportReport')?.addEventListener('click',()=>{downloadText(`MB_Gestor_Diagnostico_V${APP_VERSION.replaceAll('.','_')}_${isoToday()}.txt`,report);addAudit('Relatório de suporte gerado',`V${APP_VERSION} • ${result.summaryLabel}`);saveState();toast('Relatório de suporte gerado sem dados pessoais.');});
    $('#copySupportReport')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(report);toast('Relatório copiado.')}catch{toast('Não foi possível copiar automaticamente. Use “Baixar relatório”.')}});
  }

  async function sha256Hex(text=''){
    try{
      if(!globalThis.crypto?.subtle||!globalThis.TextEncoder)return '';
      const data=new TextEncoder().encode(String(text)),hash=await crypto.subtle.digest('SHA-256',data);
      return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');
    }catch{return ''}
  }

